import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

public class Main {
    static DataInputStream in = new DataInputStream(new BufferedInputStream(System.in, 1 << 16));

    static String next() throws IOException {
        int c = in.read();
        while (c <= ' ') c = in.read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') { sb.append((char) c); c = in.read(); }
        return sb.toString();
    }

    static int nextInt() throws IOException {
        int c = in.read();
        while (c < '0' || c > '9') c = in.read();
        int x = 0;
        while (c >= '0' && c <= '9') { x = x * 10 + (c - '0'); c = in.read(); }
        return x;
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), m = nextInt();
        String[][] own = new String[n][];
        TreeSet<String> all = new TreeSet<>();
        for (int i = 0; i < n; i++) {
            int k = nextInt();
            own[i] = new String[k];
            for (int j = 0; j < k; j++) { own[i][j] = next(); all.add(own[i][j]); }
        }
        // Sorted permission names: bit i of a role's bitset stands for names[i].
        String[] names = all.toArray(new String[0]);
        HashMap<String, Integer> index = new HashMap<>();
        for (int i = 0; i < names.length; i++) index.put(names[i], i);
        int words = (names.length + 63) / 64;
        long[][] bits = new long[n][words];
        for (int i = 0; i < n; i++)
            for (String s : own[i]) { int id = index.get(s); bits[i][id >> 6] |= 1L << (id & 63); }
        int[] head = new int[n], next = new int[m], to = new int[m], indegree = new int[n];
        Arrays.fill(head, -1);
        for (int j = 0; j < m; j++) {
            int u = nextInt(), v = nextInt();
            to[j] = v; next[j] = head[u]; head[u] = j;
            indegree[v]++;
        }
        // Kahn's algorithm: a role is final once all its parents have been merged into it.
        int[] order = new int[n];
        int tail = 0;
        for (int i = 0; i < n; i++) if (indegree[i] == 0) order[tail++] = i;
        for (int h = 0; h < tail; h++) {
            int u = order[h];
            for (int e = head[u]; e != -1; e = next[e]) {
                int v = to[e];
                long[] a = bits[v], b = bits[u];
                for (int w = 0; w < words; w++) a[w] |= b[w];
                if (--indegree[v] == 0) order[tail++] = v;
            }
        }
        byte[][] nameBytes = new byte[names.length][];
        for (int i = 0; i < names.length; i++) nameBytes[i] = names[i].getBytes(StandardCharsets.ISO_8859_1);
        BufferedOutputStream out = new BufferedOutputStream(System.out, 1 << 16);
        for (int i = 0; i < n; i++) {
            int count = 0;
            for (long x : bits[i]) count += Long.bitCount(x);
            out.write(Integer.toString(count).getBytes());
            for (int w = 0; w < words; w++) {
                for (long x = bits[i][w]; x != 0; x &= x - 1) {
                    out.write(' ');
                    out.write(nameBytes[(w << 6) + Long.numberOfTrailingZeros(x)]);
                }
            }
            out.write('\n');
        }
        out.flush();
    }
}

package main

import (
	"bufio"
	"math/bits"
	"os"
	"sort"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<20)
	sc.Split(bufio.ScanWords)
	next := func() string { sc.Scan(); return sc.Text() }
	nextInt := func() int { v, _ := strconv.Atoi(next()); return v }
	n, m := nextInt(), nextInt()
	own := make([][]string, n)
	seen := map[string]bool{}
	for i := range own {
		k := nextInt()
		own[i] = make([]string, k)
		for j := range own[i] {
			own[i][j] = next()
			seen[own[i][j]] = true
		}
	}
	// Sorted permission names: bit i of a role's bitset stands for names[i].
	names := make([]string, 0, len(seen))
	for s := range seen {
		names = append(names, s)
	}
	sort.Strings(names)
	index := make(map[string]int, len(names))
	for i, s := range names {
		index[s] = i
	}
	words := (len(names) + 63) / 64
	set := make([][]uint64, n)
	for i := range set {
		set[i] = make([]uint64, words)
		for _, s := range own[i] {
			id := index[s]
			set[i][id>>6] |= 1 << (id & 63)
		}
	}
	children := make([][]int, n)
	indegree := make([]int, n)
	for j := 0; j < m; j++ {
		u, v := nextInt(), nextInt()
		children[u] = append(children[u], v)
		indegree[v]++
	}
	// Kahn's algorithm: a role is final once all its parents have been merged into it.
	order := make([]int, 0, n)
	for i := 0; i < n; i++ {
		if indegree[i] == 0 {
			order = append(order, i)
		}
	}
	for h := 0; h < len(order); h++ {
		u := order[h]
		for _, v := range children[u] {
			a, b := set[v], set[u]
			for w := range a {
				a[w] |= b[w]
			}
			indegree[v]--
			if indegree[v] == 0 {
				order = append(order, v)
			}
		}
	}
	out := bufio.NewWriterSize(os.Stdout, 1<<16)
	defer out.Flush()
	for i := 0; i < n; i++ {
		count := 0
		for _, x := range set[i] {
			count += bits.OnesCount64(x)
		}
		out.WriteString(strconv.Itoa(count))
		for w, x := range set[i] {
			for ; x != 0; x &= x - 1 {
				out.WriteByte(' ')
				out.WriteString(names[w<<6+bits.TrailingZeros64(x)])
			}
		}
		out.WriteByte('\n')
	}
}
